INSERT INTO entity_citations
  (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order)
VALUES
('CIT_ALCYONEUS_APOLLOD','ENT_ALCYONEUS','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Library 1.6.1-2','Hercules first shot Alcyoneus with an arrow, but when the giant fell on the ground he somewhat revived. However, at Athena''s advice Hercules dragged him outside Pallene, and so the giant died.','J. G. Frazer',1921,'https://www.theoi.com/Text/Apollodorus1.html',NULL,'primary-verbatim',NULL,true,'Named in the Gigantomachy of Apollodorus 1.6 (Frazer); verify section.',DATE '2026-06-26','name + substring gate against Frazer Apollodorus',1),
('CIT_PORPHYRION_APOLLOD','ENT_PORPHYRION','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Library 1.6.1-2','But in the battle Porphyrion attacked Hercules and Hera. Nevertheless Zeus inspired him with lust for Hera, and when he tore her robes and would have forced her, she called for help, and Zeus smote him with a thunderbolt, and Hercules shot him dead with an arrow.','J. G. Frazer',1921,'https://www.theoi.com/Text/Apollodorus1.html',NULL,'primary-verbatim',NULL,true,'Named in the Gigantomachy of Apollodorus 1.6 (Frazer); verify section.',DATE '2026-06-26','name + substring gate against Frazer Apollodorus',1),
('CIT_MIMAS_APOLLOD','ENT_MIMAS','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Library 1.6.1-2','Mimas by Hephaestus with missiles of red-hot metal.','J. G. Frazer',1921,'https://www.theoi.com/Text/Apollodorus1.html',NULL,'primary-verbatim',NULL,true,'Named in the Gigantomachy of Apollodorus 1.6 (Frazer); verify section.',DATE '2026-06-26','name + substring gate against Frazer Apollodorus',1),
('CIT_ENCELADUS_APOLLOD','ENT_ENCELADUS','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Library 1.6.1-2','Enceladus fled, but Athena threw on him in his flight the island of Sicily','J. G. Frazer',1921,'https://www.theoi.com/Text/Apollodorus1.html',NULL,'primary-verbatim',NULL,true,'Named in the Gigantomachy of Apollodorus 1.6 (Frazer); verify section.',DATE '2026-06-26','name + substring gate against Frazer Apollodorus',1),
('CIT_POLYBOTES_APOLLOD','ENT_POLYBOTES','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Library 1.6.1-2','Polybotes was chased through the sea by Poseidon and came to Cos; and Poseidon, breaking off that piece of the island which is called Nisyrum, threw it on him.','J. G. Frazer',1921,'https://www.theoi.com/Text/Apollodorus1.html',NULL,'primary-verbatim',NULL,true,'Named in the Gigantomachy of Apollodorus 1.6 (Frazer); verify section.',DATE '2026-06-26','name + substring gate against Frazer Apollodorus',1),
('CIT_GRATION_APOLLOD','ENT_GRATION','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Library 1.6.1-2','Artemis slew Gration.','J. G. Frazer',1921,'https://www.theoi.com/Text/Apollodorus1.html',NULL,'primary-verbatim',NULL,true,'Named in the Gigantomachy of Apollodorus 1.6 (Frazer); verify section.',DATE '2026-06-26','name + substring gate against Frazer Apollodorus',1),
